using OdinVault.Manager.Wpf.Infrastructure;using OdinVault.Manager.Wpf.Services;namespace OdinVault.Manager.Wpf.ViewModels;internal sealed class MobileViewModel:ObservableObject{readonly AgentDashboardClient c;string scheme="http",host="",port="5188",status="";bool busy,showKey;public string Scheme{get=>scheme;set{if(Set(ref scheme,value))Raise(nameof(Preview));}}public string Host{get=>host;set{if(Set(ref host,value))Raise(nameof(Preview));}}public string Port{get=>port;set{if(Set(ref port,value))Raise(nameof(Preview));}}public string ApiKey=>c.GetApiKey();public bool ShowKey{get=>showKey;set=>Set(ref showKey,value);}public string Status{get=>status;private set=>Set(ref status,value);}public bool Busy{get=>busy;private set=>Set(ref busy,value);}public string Preview{get{try{return BuildUrl();}catch{return "آدرس ناقص یا نامعتبر";}}}public MobileViewModel(AgentDashboardClient client){c=client;Load();}void Load(){var current=c.GetMobileBaseUrl();if(Uri.TryCreate(current,UriKind.Absolute,out var u)){Scheme=u.Scheme;Host=u.Host;Port=u.IsDefaultPort?"":u.Port.ToString();}}string BuildUrl(){if(Scheme is not("http" or "https"))throw new InvalidOperationException("Protocol نامعتبر است.");if(Uri.CheckHostName(Host.Trim())==UriHostNameType.Unknown)throw new InvalidOperationException("Host نامعتبر است.");int? p=null;if(!string.IsNullOrWhiteSpace(Port)){if(!int.TryParse(Port,out var n)||n is<1 or>65535)throw new InvalidOperationException("Port نامعتبر است.");p=n;}return new UriBuilder(Scheme,Host.Trim()){Port=p??-1}.Uri.GetLeftPart(UriPartial.Authority).TrimEnd('/');}public void Save(){var url=BuildUrl();c.SaveMobileBaseUrl(url);Status=$"آدرس ذخیره شد: {url}";}public async Task TestAgentAsync(){Busy=true;try{var r=await c.TestAgentEndpointAsync(BuildUrl());Status=r.Success?$"Agent پاسخ داد: {r.Message}":$"اتصال Agent ناموفق بود: {r.Message}";}catch(Exception e){Status=e.Message;}finally{Busy=false;}}public async Task TestPortAsync(){Busy=true;try{var p=string.IsNullOrWhiteSpace(Port)?(Scheme=="https"?443:80):int.Parse(Port);var r=await c.TestPortAsync(Host.Trim(),p);Status=r.IsOpen?$"Port باز است — {r.LatencyMilliseconds:0} ms":$"Port در دسترس نیست: {r.Error}";}catch(Exception e){Status=e.Message;}finally{Busy=false;}}}